        // sends 2300 gas and will revert if the recipient is a contract without a payable fallback.
        // The test contract inherits Test, which inherits DSTest, etc. None have a receive/fallback.
        // So transfer will revert. call will not revert, will return false. So we can test the difference.
        // We don't need an external helper; the test contract itself is the adversarial receiver.
        // So we just call c.withdraw(amount).

        // Record balance before
        uint256 beforeBal = address(c).balance;
        // call withdraw
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));
        // Reference (transfer) will revert if target rejects -> success=false
        // Buggy (call) will succeed but ETH not moved -> success=true
        // The general property: if the owner rejects ETH, a call to withdraw must revert (i.e., success must be false).
        assertTrue(!success, "Withdraw should revert when owner rejects ETH");
    }
}

